compile.workshop:
variables {
    global:
        3: a
        127: top
    player:
        7: b
}

subroutines {
    0: loose
    2: helper
    5: pinned
}

rule ("Initialize global variables") {
    event {
        Ongoing - Global;
    }
    actions {
        Set Global Variable(a, 5);
        Set Global Variable(top, 1);
    }
}

rule ("Initialize player variables") {
    event {
        Ongoing - Each Player;
        All;
        All;
    }
    actions {
        Set Player Variable(Event Player, b, 9);
    }
}

rule ("uses the declared names") {
    event {
        Ongoing - Each Player;
        All;
        All;
    }
    actions {
        Modify Global Variable(a, Add, 1);
        Modify Player Variable(Event Player, b, Add, 1);
        Call Subroutine(helper);
        Call Subroutine(loose);
        Call Subroutine(pinned);
    }
}

